import * as THREE from 'three/webgpu';
import { texture as tslTexture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture from asset URL
  const textureResource = ctx.textureLoader.load(config.assets.imageUrl);
  textureResource.colorSpace = THREE.SRGBColorSpace;
  textureResource.magFilter = THREE.LinearFilter;
  textureResource.minFilter = THREE.LinearMipmapLinearFilter;

  // Create plane geometry with aspect ratio matching atlas region (512/320)
  const aspectRatio = 512 / 320;
  const height = 1.0;
  const width = height * aspectRatio;
  const geometry = new THREE.PlaneGeometry(width, height);

  // Create material using TSL for WebGPU
  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = tslTexture(textureResource);
  material.side = THREE.DoubleSide;

  // Create mesh with configured position, rotation, scale
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(config.position[0], config.position[1], config.position[2]);
  mesh.rotation.set(config.rotation[0], config.rotation[1], config.rotation[2]);
  mesh.scale.set(config.scale[0], config.scale[1], config.scale[2]);

  group.add(mesh);

  // Billboard behavior handler - sprite always faces camera
  group.userData.handlers = {
    update: (camera) => {
      if (camera) {
        mesh.lookAt(camera.position);
      }
    }
  };

  // Resource cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureResource.dispose();
  };

  return group;
}
